unitsize(0.5cm);
pair A,B,C,D,M,R,P,Q;
A=(0,4);
B=(4,4);
C=(4,0);
D=(0,0);
M=(2,0);
R=(3.2,0);
P=(3.2,1.6);
Q=(0,1.6);
