foo = (1/2/(1/4 + t^2),-t/(1/4 + t^2));
Q = (1/2/(1/4 + t^2),-t/(1/4 + t^2));

t = -1/(2*sqrt(3));
foo = (1/2/(1/4 + t^2),-t/(1/4 + t^2));
P = (1/2/(1/4 + t^2),-t/(1/4 + t^2));

for (t = -1/(2*sqrt(3)); t <= 1/(2*sqrt(3)); t = t + 0.01) {
  foo = foo--(1/2/(1/4 + t^2),-t/(1/4 + t^2));
}

draw(foo,red);
draw(A--B--C--D--E--F--cycle);
draw((-1,0)--(2.5,0));
